CREATE DATABASE mostaa_chat;GO
USE mostaa_chat;GO
CREATE TABLE tenants(id uniqueidentifier PRIMARY KEY DEFAULT NEWID(),name nvarchar(200) NOT NULL,slug nvarchar(100) UNIQUE NOT NULL,plan varchar(30) NOT NULL,active bit NOT NULL DEFAULT 1,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE users(id uniqueidentifier PRIMARY KEY DEFAULT NEWID(),tenant_id uniqueidentifier NOT NULL REFERENCES tenants(id),email nvarchar(320),phone nvarchar(40),display_name nvarchar(200) NOT NULL,role varchar(40) NOT NULL,active bit NOT NULL DEFAULT 1,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE customers(id uniqueidentifier PRIMARY KEY DEFAULT NEWID(),tenant_id uniqueidentifier NOT NULL REFERENCES tenants(id),display_name nvarchar(200) NOT NULL,phone nvarchar(40),email nvarchar(320),verified bit DEFAULT 0,created_at datetime2 DEFAULT SYSUTCDATETIME());
CREATE TABLE customer_identities(id uniqueidentifier PRIMARY KEY DEFAULT NEWID(),tenant_id uniqueidentifier NOT NULL REFERENCES tenants(id),customer_id uniqueidentifier NOT NULL REFERENCES customers(id),provider varchar(40) NOT NULL,provider_user_id nvarchar(300) NOT NULL,verified bit DEFAULT 0,UNIQUE(tenant_id,provider,provider_user_id));
CREATE TABLE channels(id uniqueidentifier PRIMARY KEY DEFAULT NEWID(),tenant_id uniqueidentifier NOT NULL REFERENCES tenants(id),provider varchar(40) NOT NULL,external_account_id nvarchar(300) NOT NULL,display_name nvarchar(200) NOT NULL,secret_ciphertext varbinary(max),enabled bit DEFAULT 1,UNIQUE(tenant_id,provider,external_account_id));
CREATE TABLE conversations(id uniqueidentifier PRIMARY KEY DEFAULT NEWID(),tenant_id uniqueidentifier NOT NULL REFERENCES tenants(id),customer_id uniqueidentifier NOT NULL REFERENCES customers(id),channel_id uniqueidentifier NOT NULL REFERENCES channels(id),status varchar(30) DEFAULT 'unassigned',assigned_user_id uniqueidentifier NULL REFERENCES users(id),lock_owner_id uniqueidentifier NULL REFERENCES users(id),lock_expires_at datetime2 NULL,created_at datetime2 DEFAULT SYSUTCDATETIME(),updated_at datetime2 DEFAULT SYSUTCDATETIME());
CREATE INDEX ix_conversations_queue ON conversations(tenant_id,status,updated_at DESC);
CREATE TABLE messages(id uniqueidentifier PRIMARY KEY DEFAULT NEWID(),tenant_id uniqueidentifier NOT NULL REFERENCES tenants(id),conversation_id uniqueidentifier NOT NULL REFERENCES conversations(id),provider_message_id nvarchar(300),client_idempotency_key nvarchar(200),direction varchar(10) NOT NULL,message_type varchar(30) NOT NULL,body nvarchar(max),media_url nvarchar(1000),transcript nvarchar(max),status varchar(30),created_at datetime2 DEFAULT SYSUTCDATETIME(),UNIQUE(tenant_id,provider_message_id),UNIQUE(tenant_id,client_idempotency_key));
CREATE TABLE webhook_events(id uniqueidentifier PRIMARY KEY DEFAULT NEWID(),provider varchar(40),provider_event_id nvarchar(300) UNIQUE,payload_json nvarchar(max),status varchar(30),received_at datetime2 DEFAULT SYSUTCDATETIME());
CREATE TABLE orders(id uniqueidentifier PRIMARY KEY DEFAULT NEWID(),tenant_id uniqueidentifier NOT NULL REFERENCES tenants(id),customer_id uniqueidentifier REFERENCES customers(id),external_reference nvarchar(200),status varchar(40),total decimal(18,2),currency char(3),created_at datetime2 DEFAULT SYSUTCDATETIME());
CREATE TABLE payments(id uniqueidentifier PRIMARY KEY DEFAULT NEWID(),tenant_id uniqueidentifier NOT NULL REFERENCES tenants(id),provider varchar(20) NOT NULL,plan varchar(30),amount decimal(18,2),currency char(3),transaction_reference nvarchar(300),receipt_url nvarchar(1000),status varchar(30) DEFAULT 'pending_verification',verified_by uniqueidentifier NULL REFERENCES users(id),verified_at datetime2 NULL,created_at datetime2 DEFAULT SYSUTCDATETIME());
CREATE TABLE audit_logs(id bigint IDENTITY PRIMARY KEY,tenant_id uniqueidentifier,actor_user_id uniqueidentifier,action nvarchar(100),entity_type nvarchar(100),entity_id nvarchar(200),details_json nvarchar(max),created_at datetime2 DEFAULT SYSUTCDATETIME());GO
